const hasDependents = `-- name: HasDependents :one

SELECT EXISTS(
    SELECT 1 FROM patient_dependents
    WHERE patient_id = $1
) as has_dependents
`

// ============================================
// VALIDATION & UTILITIES
// ============================================
func (q *Queries) HasDependents(ctx context.Context, patientID pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, hasDependents, patientID)
	var has_dependents bool
	err := row.Scan(&has_dependents)
	return has_dependents, err
}

